org.machanism.machai.ai.provider.Genai provider = new org.machanism.machai.ai.provider.impl.OpenAIProvider();
provider.init("gpt-4.1", configurator);
provider.instructions("Answer concisely.");
provider.prompt("Summarize this architecture.");
java.lang.String answer = provider.perform();
provider.clear();

org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("OpenAI:gpt-4o-mini", configurator);
provider.prompt("Draft a release summary.");
java.lang.String result = provider.perform();

provider.addTools(new com.example.tools.ProjectTools());
provider.prompt("Use the project tool to inspect the requested file.");
java.lang.String result = provider.perform();

org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("OpenAI:gpt-4o-mini", configurator);
provider.prompt("Explain the configured workflow.");
java.lang.String response = provider.perform();

public final class com.example.tools.ProjectTools implements org.machanism.machai.ai.tools.FunctionTools {
    @org.machanism.machai.ai.tools.Tool(name = "project_status", description = "Returns project status.")
    public java.lang.String projectStatus() { return "ready"; }
}

org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("OpenAI:gpt-4o-mini", configurator);
provider.instructions("Provide a concise technical answer.");
provider.prompt("Summarize the release notes.");
java.lang.String answer = provider.perform();
provider.clear();

org.machanism.machai.ai.tools.FunctionToolsLoader loader = new org.machanism.machai.ai.tools.FunctionToolsLoader();
loader.applyTools(provider, com.example.app.MyApplication.class);
provider.prompt("Use the available project_status tool.");
java.lang.String answer = provider.perform();
